    ```tsx
    import React from "react";

    interface UserProps {
      name: string;
      age: number;
    }

    function User({ name, age }: UserProps) {
      return (
        <>
          <h1>{`Welcome, ${name}`}</h1>
          <h2>{`Age, ${age}`}</h2>
        </>
      );
