    if (s1.Length != s2.Length)
        return false;

    int[] a = new int[256];
    int n = s1.Length;
    for (int i = 0; i < n; i++)
    {
        int c1 = (int)s1[i];
        int c2 = (int)s2[i];

        a[c1]++;
        a[c2]--;
    }

