    { 
      if(node.left === null) 
      { 
        node.left = newNode; 
      } else { 
        this.insertNode(node.left, newNode); 
      } 
    } 
    else { 
      if(node.right === null) 
      { 
        node.right = newNode; 
      } else { 
        this.insertNode(node.right,newNode); 
      } 
    } 
  } 
}
