### Real Coding Task: How would you check if two strings are anagrams in JavaScript?

**Role**: Java Developer | **Category**: Coding | **Difficulty**: Hard

#### Problem Description
How would you check if two strings are anagrams in JavaScript?

#### Verified Solution & Code Implementation
```text
function isAnagram(str1, str2) { 
  // Compare the length of the two string
  if (str1.length !== str2.length) { 
    return false; 
  } 

  // Convert both strings to lowercase
  str1 = str1.toLowerCase(); 
  str2 = str2.toLowerCase(); 

  // Store the frequency of characters
  // in the first string
  const frequencyCounter1 = {}; 
  for (let char of str1) { 
    frequencyCounter1[char] = (frequencyCounter1[char] || 0) + 1; 
  } 

  // Store the frequency of characters
  // in the second string
  const frequencyCounter2 = {}; 
  for (let char of str2) { 
    frequencyCounter2[char] = (frequencyCounter2[char] || 0) + 1; 
  }

  // Compare the frequency of characters 
  for (let key in frequencyCounter1) { 
    if (!(key in frequencyCounter2)) { 
      return false; 
    } 

    if (frequencyCounter2[key] !== frequencyCounter1[key]) { 
      return false; 
    } 
  }  
  return true; 
}
```

