**Input Specification**:
```
50
```

#### Verified Solution & Code Implementation
```text
import java.util.Arrays; 

class CloseNumber { 

    // function to find 10 numbers closest to x 
    static void closeNums(int x, int arr[], int n) 
    { 
        // array which stores 10 numbers 
        // closest to x 
        int result[] = new int[10]; 
        int index = 0; 

        // initialize difference between 
        // x and arr[i] 
        int dif = Integer.MAX_VALUE; 

        // traverse in the array and 
        // find the 10 closest numbers 
        for (int i = 0; i < n; i++) { 
            if (x == arr[i]) 
                continue; 
            if (Math.abs(x - arr[i]) < dif) { 
                result[index++] = arr[i]; 
                if (index == 10) { 
                    Arrays.sort(result); 
                    index--; 
                } 

                // update dif 
                if (index > 0) 
                    dif = Math.abs(x - result[index - 1]); 
            } 
        } 

        // print the 10 closest numbers 
        for (int i = 0; i < 10; i++) 
            System.out.print(result[i] + " "); 
    } 

    // Driver Code 
    public static void main(String[] args) 
    { 
        int arr[] = { 43, 3, 11, 15, 78, 
                    88, 24, 50, 36, 44 }; 
        int x = 50; 

        int n = arr.length; 
        closeNums(x, arr, n); 
    } 
}
