function longestCommonSubsequence(sequence1, sequence2) {
 let dp = [];

 for(let i=0; i<=sequence1.length; i++) {
  dp.push([]);
  for(let j=0; j<=sequence2.length; j++) {
   dp[i][j] = 0;
  }
