public class PerfectNumber {

    public static boolean isPerfectNumber(int number) {
        int sum = 0;
        // loop to add all the divisors
        for (int i = 1; i < number; i++) 
        { 
            if (number % i == 0) 
            {
                sum += i; 
            }
        } 
        // check to determine if the number is perfect
        if(sum == number) { 
            return true; 
        }
        else {
            return false; 
        }
    }

