### Real Coding Task: Write a C# program to sort a given array using the Quick Sort algorithm.

**Role**: Python Developer | **Category**: Coding | **Difficulty**: Hard

#### Problem Description
Write a C# program to sort a given array using the Quick Sort algorithm.
**Input Specification**:
```
array = [8, 4, 1, 9, 6]
```

#### Verified Solution & Code Implementation
```text
using System;

namespace QuickSortExample
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] array = { 8, 4, 1, 9, 6 };
            int left = 0;
            int right = array.Length - 1;

            quickSort(array, left, right);

            Console.WriteLine("Sorted array is:");
            foreach (int val in array)
            {
                Console.WriteLine(val);
            }

        }

        static void quickSort(int[] array, int left, int right)
        {
            if (left < right)
            {
                int pivotIndex = partition(array, left, right);

                quickSort(array, left, pivotIndex - 1);
                quickSort(array, pivotIndex + 1, right);
            }
        }

        static int partition(int[] array, int left, int right)
        {
            int pivot = array[right];
            int pivotIndex = left;

            for (int i = left; i < right; i++)
            {
                if (array[i] <= pivot)
                {
                    swap(array, i, pivotIndex);
                    pivotIndex++;
                }
            }

            swap(array, right, pivotIndex);

            return pivotIndex;
        }

        static void swap(int[] array, int i, int j)
        {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
}
```

