### Real Coding Task: How would you transform a JSON object into an XML document with JavaScript?

**Role**: Java Developer | **Category**: Coding | **Difficulty**: Hard

#### Problem Description
How would you transform a JSON object into an XML document with JavaScript?

#### Verified Solution & Code Implementation
```text
function json2xml(json) {
  // Create the return variable
  let xml = '';

  // Parse the input
  if (typeof json == 'object') {
    for (let key in json) {
      // Add a start tag
      xml += '<' + key + '>';

      // Check for child elements
      if (typeof json[key] == 'object') {
        // Recursively traverse the child elements
        xml += json2xml(json[key]);
      } else if (typeof json[key] == 'string') {
        // Add a value
        xml += json[key];
      } else {
        // Add nothing
      }

      // Add an end tag
      xml += '</' + key + '>';
    }
  } else if (typeof json == 'string') {
    // Add the value
    xml += json;
  } else {
    // Add nothing
  }

  // Return the XML
  return xml;
}
```

